import fs from "node:fs/promises";
import path from "node:path";
import { env } from "./env";

/**
 * Object storage for report photos. Production hosts (Vercel) have a read-only
 * filesystem, so photos go to Vercel Blob when BLOB_READ_WRITE_TOKEN is set;
 * otherwise they are written under DATA_DIR/uploads for local use.
 *
 * Keys are generated by the server (never from user filenames). Blobs are
 * stored with public access but an unguessable path; they are only linked
 * from the moderation queue.
 */
export async function putObject(key: string, body: Buffer, contentType: string): Promise<{ key: string; url: string | null }> {
  if (!/^[a-z0-9/_-]+\.[a-z0-9]+$/i.test(key) || key.includes("..")) throw new Error("invalid storage key");
  const e = env();
  if (e.BLOB_READ_WRITE_TOKEN) {
    const { put } = await import("@vercel/blob");
    const res = await put(key, body, { access: "public", contentType, token: e.BLOB_READ_WRITE_TOKEN, addRandomSuffix: true });
    return { key: res.pathname, url: res.url };
  }
  const dir = path.join(process.cwd(), e.DATA_DIR, "uploads");
  const file = path.join(dir, key);
  const rel = path.relative(dir, file);
  if (!rel || rel.startsWith("..") || path.isAbsolute(rel)) throw new Error("invalid storage key");
  await fs.mkdir(path.dirname(file), { recursive: true });
  await fs.writeFile(file, body);
  return { key, url: null };
}
